--** GroupBY
-- !GROUP BY allows us to divide rows into groups based on a column and perform calculations on each group.

--!Total revenue generated by each city
SELECT 
    city ,
    SUM(amount) AS total_revenue 
FROM orders 
GROUP BY city
ORDER BY total_revenue ;

--! how many orders are in each status
SELECT  
    status ,
    COUNT(*) AS total_orders 
FROM orders 
GROUP BY status;

--! average order amount for each customer.
SELECT 
    customer_id,
    AVG(amount) AS avg_amount
FROM orders
GROUP BY customer_id;


SELECT
    customer_id,
    COUNT(*) AS total_orders,
    SUM(amount) AS total_spent,
    AVG(amount) AS average_order,
    MAX(amount) AS highest_order,
    MIN(amount) AS lowest_order
FROM orders
GROUP BY customer_id;